.sidebar[data-collapsed] .sectionLabel > span {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}
.rows {
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.row {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--v4-space-10);
  width: 100%;
  min-width: 0;
  height: var(--v4-size-control-md);
  padding: 0 9px;
  border: 0;
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background: transparent;
  color: var(--v4-text2);
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
  text-align: start;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition-property: background-color, color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-standard);
}
.row:hover {
  background: var(--v4-sidebar-hover);
  color: var(--v4-ink);
}
.row:active {
  background: linear-gradient(var(--v4-segment-hover) 0 0) var(--v4-sidebar-hover);
}
.row:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.row[data-current],
.row[data-current]:hover,
.row[data-current]:active {
  background: var(--v4-sidebar-current);
  color: var(--v4-ink);
  font-weight: 600;
}
.row[data-holds-current] {
  color: var(--v4-ink);
}
.sidebar[data-collapsed] .row[data-holds-current] {
  background: var(--v4-sidebar-current);
}
.row:disabled,
.row[aria-disabled="true"] {
  background: transparent;
  color: var(--v4-faint);
  cursor: not-allowed;
}
.row[data-child] {
  height: var(--v4-size-control-sm);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
}
.icon {
  flex: none;
}
.label {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.count {
  flex: none;
}
.dot {
  display: none;
}
.trailing,
.chevron {
  flex: none;
  color: var(--v4-muted);
}
.chevron {
  transition-property: transform;
  transition-duration: var(--v4-duration-slow);
  transition-timing-function: var(--v4-ease-standard);
}
.row[aria-expanded="true"] > .chevron {
  transform: rotate(90deg);
}
.row[data-current] .trailing {
  color: inherit;
}
.children {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 1px;
  margin: 0;
  padding: 1px 0 0 28px;
  list-style: none;
}
.children::before {
  content: "";
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 18px;
  width: 1px;
  background: var(--v4-sidebar-line);
  pointer-events: none;
}
.children[hidden] {
  display: none;
}
.sidebar[data-collapsed] .label,
.sidebar[data-collapsed] .count,
.sidebar[data-collapsed] .trailing,
.sidebar[data-collapsed] .chevron,
.sidebar[data-collapsed] .accountText {
  display: none;
}
.sidebar[data-collapsed] .row {
  width: var(--v4-size-control-md);
}
.sidebar[data-collapsed] .dot {
  position: absolute;
  top: 6px;
  left: 25px;
  display: block;
  width: 6px;
  height: 6px;
  border-radius: calc(var(--v4-radius-xs) * var(--corners));
  background: var(--v4-accent-fg);
  box-shadow: 0 0 0 2px var(--v4-sidebar);
  pointer-events: none;
}
.sidebar[data-collapsed] .row:hover .dot {
  box-shadow: 0 0 0 2px var(--v4-sidebar-hover);
}
.sidebar[data-collapsed] .row:is([data-current], [data-holds-current]) .dot {
  box-shadow: 0 0 0 2px var(--v4-sidebar-current);
}
.footer {
  flex: none;
  padding: 0 var(--v4-space-8);
}
.accountShelf {
  flex: none;
  padding: var(--v4-space-8);
  border-top: 1px solid var(--v4-sidebar-line);
}
.account {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-width: 0;
  height: var(--v4-size-control-md);
  padding: 0 9px 0 var(--v4-space-8);
  border: 0;
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background: transparent;
  color: var(--v4-ink);
  text-align: start;
  cursor: pointer;
}
.account:hover,
.account[aria-expanded="true"] {
  background: var(--v4-sidebar-hover);
}
.account:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.sidebar[data-collapsed] .account {
  width: var(--v4-size-control-md);
}
.accountText {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.accountName,
.accountMeta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.accountName {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: 600;
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.accountMeta {
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: 400;
  letter-spacing: var(--v4-type-caption-letter-spacing);
}
.themeRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-8);
  min-height: var(--v4-size-control-sm);
  padding-inline: var(--v4-space-8);
  color: var(--v4-ink);
}
.userRow {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  width: 100%;
  padding: var(--v4-space-6) var(--v4-space-8);
  border: 0;
  border-radius: calc((var(--v4-radius-pop) - var(--v4-space-3)) * var(--corners));
  background: transparent;
  color: var(--v4-ink);
  text-align: start;
  text-decoration: none;
  cursor: pointer;
}
.userRow:hover {
  background: color-mix(in oklab, var(--v4-ink) var(--overlay-hover, var(--v4-opacity-hover)), transparent);
}
.userRow [data-slot="identity"] [data-slot="avatar"],
.account [data-slot="avatar"] {
  background: var(--v4-ink);
  color: var(--v4-on-ink);
}
.userRow [data-slot="identity"] [data-slot="avatar"]::after,
.account [data-slot="avatar"]::after {
  border-color: transparent;
}
.userRow [data-slot="identity"] [data-slot="avatar"] > *,
.account [data-slot="avatar"] > * {
  background: transparent;
  color: inherit;
}
.userRow [data-slot="identity"] > div > :first-child {
  font-weight: 600;
}
.userRow [data-slot="identity"] > div > :last-child {
  color: var(--v4-muted);
}
.userRow:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.userRow > :first-child {
  flex: 1 1 auto;
  min-width: 0;
}
.back {
  color: var(--v4-muted);
}
.back:hover {
  color: var(--v4-ink);
}
.nav[data-enter="forward"] {
  animation: scopeForward var(--v4-duration-moderate) var(--v4-ease-standard) both;
}
.nav[data-enter="back"] {
  animation: scopeBack var(--v4-duration-moderate) var(--v4-ease-standard) both;
}
@keyframes scopeForward {
  from {
    opacity: 0;
    translate: var(--v4-space-16) 0;
  }
}
@keyframes scopeBack {
  from {
    opacity: 0;
    translate: calc(-1 * var(--v4-space-16)) 0;
  }
}
@keyframes scopeFade {
  from {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .nav[data-enter] {
    animation-name: scopeFade;
  }
}
